//! Writes the frozen fixture into `fixtures/release-1/`.
//!
//! `cargo run -p spot-journal-compat --bin gen_fixture` writes the committed fixture in place;
//! with one argument it writes into that directory instead (for a diff, or for a fresh checkout).
//! The generated bytes are committed: see `fixtures/README.md` for why, and for when regeneration
//! is the right answer (a deliberate format change, never a red determinism test).

use std::path::PathBuf;

fn main() {
    let target = std::env::args()
        .nth(1)
        .map_or_else(spot_journal_compat::generator::default_dir, PathBuf::from);
    match spot_journal_compat::generator::write(&target) {
        Ok(written) => println!("wrote {written} file(s) into {}", target.display()),
        Err(error) => {
            eprintln!("gen_fixture: {error}");
            std::process::exit(1);
        }
    }
}
